// Coin conditioning and game latches at bottom centre. Analogue-node inputs
// are separated from digital outputs so RC delays are not silently erased.
// Wire names follow docs/NET_NAMES.md.
`timescale 1ns/1ps
`default_nettype none
module fonz_coin_latch_fpga(
    input wire clk_sys,rst,
    input wire CN21_IC38_pin1,CN20_IC38_pin13,
    input wire R76_C51_IC38_pin9,
    output wire IC38_pin3_COIN_LATCH,IC38_pin11_COIN_LATCH_n,IC38_pin8_COIN
);
    // IC38 gates 1,2->3 and 12,13->11 are cross-coupled NAND gates.
    // Inputs are the conditioned connector 21/20 contact signals.
    assign IC38_pin3_COIN_LATCH=~(CN21_IC38_pin1 & IC38_pin11_COIN_LATCH_n);
    // Loop cut: the latch's IC38.11 side is a flop.
    reg IC38_pin11_COIN_LATCH_n_reg=1'b1;
    always @(posedge clk_sys) IC38_pin11_COIN_LATCH_n_reg<=rst ? 1'b1 : ~(IC38_pin3_COIN_LATCH & CN20_IC38_pin13);
    assign IC38_pin11_COIN_LATCH_n=IC38_pin11_COIN_LATCH_n_reg;
    // Pin9 is AFTER R76=220ohm/C51=680pF, not the same physical net as 38.3.
    assign IC38_pin8_COIN=~(R76_C51_IC38_pin9 & IC38_pin11_COIN_LATCH_n);
endmodule

module fonz_game_latches_fpga(
    input wire clk_sys,rst,
    input wire IC37_pin2_IC82_pin2,IC103_pin4_ANTENNA_n,IC103_pin13_ANTENNA,IC38_pin8_COIN,
    input wire IC59_pin8_THRESHOLD_n,IC103_pin12_START_n,IC82_pin13_TIME_UP,
    input wire R77_C52_IC60_pin12_IC61_pin11,
    output wire IC82_pin1_IC83_pin12,IC101_pin11_COUNT_CLEAR,IC81_pin6_TIME_LOAD_n,
    output wire IC83_pin9_GAME_LATCH,IC83_pin13_EXTEND_ARMED,IC83_pin4_EXTENDED,
    output wire IC59_pin2_R77,IC17_pin8_CONNECTOR,
    output wire IC60_pin11_IC60_pin10,IC60_pin8_IC83_pin11,IC61_pin8_EXTEND_LOAD_n
