    assign IC82_pin1_IC83_pin12=~(IC37_pin2_IC82_pin2 | IC103_pin13_ANTENNA); // pins2,3 ->1
    // S11 crosses the coin-pulse wire WITHOUT a junction and instead
    // returns from IC60.8 along the bottom of the sheet.
    fonz_74279_ce ic83c(.clk_sys(clk_sys),.rst(rst),.r_n(IC38_pin8_COIN),.s1_n(IC82_pin1_IC83_pin12),.s2_n(IC60_pin8_IC83_pin11),
        .q(IC83_pin9_GAME_LATCH));
    assign IC101_pin11_COUNT_CLEAR=~(IC103_pin12_START_n & IC103_pin4_ANTENNA_n); // pins12,13 ->11
    fonz_74279_ce ic83d(.clk_sys(clk_sys),.rst(rst),.r_n(IC103_pin12_START_n),.s1_n(IC59_pin8_THRESHOLD_n),.s2_n(1'b1),
        .q(IC83_pin13_EXTEND_ARMED));
