    assign IC81_pin6_TIME_LOAD_n=IC103_pin12_START_n & IC61_pin8_EXTEND_LOAD_n; // pins5,4 ->6
    fonz_74279_ce ic83a(.clk_sys(clk_sys),.rst(rst),.r_n(IC103_pin12_START_n),.s1_n(IC61_pin8_EXTEND_LOAD_n),.s2_n(1'b1),
        .q(IC83_pin4_EXTENDED));
