    assign IC17_pin8_CONNECTOR=~IC83_pin4_EXTENDED;    // 7406 open collector, pin9 ->8
    assign IC60_pin11_IC60_pin10=~(IC83_pin13_EXTEND_ARMED & R77_C52_IC60_pin12_IC61_pin11); // pins13,12 ->11
    assign IC60_pin8_IC83_pin11=~(IC60_pin11_IC60_pin10 & IC82_pin13_TIME_UP);  // pins10,9 ->8
    assign IC61_pin8_EXTEND_LOAD_n=~(IC83_pin13_EXTEND_ARMED & R77_C52_IC60_pin12_IC61_pin11 &
                                     IC82_pin13_TIME_UP); // pins9,11,10 ->8
    // R77=220ohm and C52=680pF lie between IC59.2 and pins IC60.12/IC61.11
    // (modelled in fonz_board by fonz_rc_edge).
endmodule

